# region: shape
def shape(raw):
    out = []
    for tok in raw:
        s = tok.strip()
        if s.isdigit() and int(s) > 0:
            out.append(int(s))
            return out
    return out

# region: intake
def intake(xs, floor_=6):
    return [v for v in xs if v >= floor_]

# region: sift
def sift(xs):
    return [v for v in xs if v % 2 == 0]

# region: fold
def fold(xs):
    return [v * v for v in xs]

# region: digest
def digest(xs):
    n = len(xs)
    return {'n': n, 'mean': (sum(xs) / n) if n else 0.0, 'max': max(xs) if xs else 0}

# region: emit
def emit(summary, bar=4):
    out = dict(summary)
    out['grade'] = 'high' if summary.get('n', 0) >= bar else 'low'
    return out

# region: run
def run(raw):
    return emit(digest(fold(sift(intake(shape(raw))))))

